action.command:
node -e "
const fs = require('fs');
const path = require('path');
const file = process.stdin.read ? '' : '';
let input = '';
process.stdin.on('data', d => input += d);
process.stdin.on('end', () => {
  try {
    const ctx = JSON.parse(input);
    const filePath = ctx && ctx.file ? ctx.file : '';
    if (filePath && filePath.endsWith('.js') && !filePath.includes('node_modules') && !filePath.includes('tests/')) {
      const src = fs.readFileSync(filePath, 'utf8');
      new Function(src.replace('module.exports', 'var _exports'));
      console.log('[TodoFlow Hook] JS syntax OK: ' + path.basename(filePath));
    }
  } catch(e) {
    process.stderr.write('[TodoFlow Hook] Issue in saved file: ' + e.message + '\n');
  }
});
"
